import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Publishing public npm tools","description":"","frontmatter":{"navigation":{"category":"CI and releases"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/npm-publishing.md"},"headers":[],"relativePath":"guides/npm-publishing.md","filePath":"docs/npm-publishing.md","lastUpdated":1792014225000}`),a={name:`guides/npm-publishing.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="publishing-public-npm-tools" tabindex="-1">Publishing public npm tools <a class="header-anchor" href="#publishing-public-npm-tools" aria-label="Permalink to “Publishing public npm tools”">​</a></h1><p>This guide covers the six public tool packages maintained in this repository. Their first versions are bootstrapped from exact Release Please tags with an authenticated npm session. Later versions are published by the GitHub Actions release workflow using npm trusted publishing.</p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Do not bootstrap or publish these packages until Plan 005&#39;s Static Hermes parity STOP gate is cleared. The <a href="../tools/static-hermes-runtime/test/wit-api-coverage.test.mjs">957-operation WIT inventory</a> is not a behavior-test map, and no one-to-one real-server behavior suite covers every operation. The current <a href="../tools/pumpkin-api/test/pumpkin-api.itest.ts">API server fixture</a> covers server-load events, delayed tasks, and command dispatch only. Linux x64 and Windows x64 external-consumer CI results from the <a href="../.github/workflows/external-consumer.yml">matrix workflow</a> are also still required. Check <code>plans/005-pumpkin-api-and-plugin-creator.md</code> and its <code>Execution status</code> section for authoritative clearance; its <code>DONE</code> index entry does not clear the explicit STOP. Registry writes also require separate maintainer authorization.</p></div><h2 id="packages-and-publish-order" tabindex="-1">Packages and publish order <a class="header-anchor" href="#packages-and-publish-order" aria-label="Permalink to “Packages and publish order”">​</a></h2><p>Use this order for first publishes and whenever related versions change. The creator&#39;s TypeScript and JavaScript templates both consume the API and build packages. The build package consumes the API and Static Hermes runtime.</p><table tabindex="0"><thead><tr><th>Order</th><th>Workspace path</th><th>npm package</th><th>First tag</th><th>Required public packages</th></tr></thead><tbody><tr><td>1</td><td><code>tools/pumpkin-api</code></td><td><code>@pumpkin-plugins/pumpkin-api</code></td><td><code>pumpkin-api-v0.1.0</code></td><td>None</td></tr><tr><td>2</td><td><code>tools/static-hermes-runtime</code></td><td><code>@pumpkin-plugins/static-hermes-runtime</code></td><td><code>static-hermes-runtime-v0.1.0</code></td><td>None</td></tr><tr><td>3</td><td><code>tools/build</code></td><td><code>@pumpkin-plugins/build</code></td><td><code>build-v0.1.0</code></td><td>The exact API and Static Hermes runtime versions in its manifest</td></tr><tr><td>4</td><td><code>tools/create-pumpkin-plugin</code></td><td><code>create-pumpkin-plugin</code></td><td><code>create-pumpkin-plugin-v0.1.0</code></td><td>The exact API and build versions required by both starter templates</td></tr><tr><td>5</td><td><code>tools/codemod</code></td><td><code>@pumpkin-plugins/codemod</code></td><td><code>codemod-v0.1.0</code></td><td>None</td></tr><tr><td>6</td><td><code>tools/cspell-dict-minecraft</code></td><td><code>@pumpkin-plugins/cspell-dict-minecraft</code></td><td><code>cspell-dict-minecraft-v0.1.0</code></td><td>None</td></tr></tbody></table><p>The order is maintained in the repository&#39;s public-tool package metadata. Do not add private tools or benchmarks to this list.</p><h2 id="bootstrap-the-first-version" tabindex="-1">Bootstrap the first version <a class="header-anchor" href="#bootstrap-the-first-version" aria-label="Permalink to “Bootstrap the first version”">​</a></h2><p>Each package&#39;s first release is <code>0.1.0</code>. The bootstrap command fetches the exact Release Please tag, installs the frozen workspace dependencies from that source, packs only the selected package, and checks its package metadata, files, and required public dependencies before publishing. Run it from the repository root with the package path and matching tag:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:bootstrap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/pumpkin-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pumpkin-api-v0.1.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:bootstrap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/pumpkin-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pumpkin-api-v0.1.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --expected-owner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm-username</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --confirm-write-access</span></span></code></pre></div><p>Use <code>--dry-run</code> first for every package. Replace the path and tag with the corresponding table row. It performs local validation and read-only registry checks; it does not publish or change trusted-publisher settings. Normal publishing requires <code>--expected-owner</code> and <code>--confirm-write-access</code>. Supply the intended npm account explicitly; the repository does not guess the npm username from its GitHub author metadata. The command checks that <code>npm whoami</code> matches the supplied account and requires account-level two-factor authentication. It prints the identity and write-access confirmation before running <code>npm publish</code>.</p><p>When a target package already exists, <code>npm owner ls</code> must list the supplied account as an owner; other maintainers may also be owners. Collaborator write access alone does not satisfy this check. For a new scoped package, the command checks that the account belongs to the <code>@pumpkin-plugins</code> npm organization. Organization membership alone does not prove package write access, so <code>--confirm-write-access</code> records the maintainer&#39;s explicit confirmation; npm remains the final authorization check during publish. An unclaimed unscoped name such as <code>create-pumpkin-plugin</code> has no package owner or collaborator list to query, so the same explicit confirmation is required and npm enforces the name claim when publishing. Stop if the intended owner or write authorization is unclear. npm accepts account-level 2FA modes <code>auth-only</code> and <code>auth-and-writes</code>.</p><p>Bootstrap all six packages in the order above. The command reads dependency versions from the selected tag&#39;s package manifests and, for the creator, both tagged template manifests. Before bootstrapping <code>build</code>, publish the exact API and Static Hermes runtime versions required by that tag. Before bootstrapping the creator, publish the exact API and build versions required by both templates. The command checks these prerequisites and stops if any required version is unavailable.</p><p>The command is safe to retry after interruption. In normal mode, it checks the expected owner and write-access confirmation even when the target <code>0.1.0</code> already exists with matching tarball integrity; then it reports the package as already bootstrapped without publishing again. A dry run performs only local and registry checks. If the published bytes differ, the supplied owner cannot be verified, write access is not confirmed, or a registry request fails for a reason other than a definitive missing-version response, stop and resolve that condition before retrying. npm versions are immutable; never try to replace an existing version.</p><h2 id="publish-later-releases" tabindex="-1">Publish later releases <a class="header-anchor" href="#publish-later-releases" aria-label="Permalink to “Publish later releases”">​</a></h2><p>After a first version exists and a later version is ready, configure that package&#39;s trusted publisher and merge the relevant Release Please PR. The <code>ci.yml</code> caller invokes the reusable release workflow after CI gates pass. The <code>publish-tools</code> job runs only when Release Please reports public tool paths to release. It processes those paths sequentially in the canonical order, checks the release tag and packed package metadata, verifies prerequisite versions, and compares the registry integrity with the local tarball before treating an existing version as complete. It publishes missing versions with npm trusted publishing and provenance. See <a href="./npm-trusted-publishing">Trusted publishing for npm tools</a> for package setup and expiry recovery.</p><p>The first <code>0.1.0</code> bootstrap does not validate OIDC. For each package, configure trust when its next real release is ready, then arrange for the first successful automated publish to finish within two days. See the <a href="./npm-trusted-publishing#configure-the-trusted-publisher">trusted-publishing guide</a>.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};